import sys;sys.path.insert(0,__import__('os').path.dirname(__file__));from mk import I
def P(i): return '매시간_5제_누적_최고난도-%03d'%i

I(P(81),"예상 오답 — 두 점을 모두 $x$축 위쪽에 두고 넓이를 계산해 $\\alpha$, $\\beta$를 잘못 정한 경우",
 ["$u=x+y$로 매개: $x=\\frac12(u+\\frac1u)$ → 부채꼴 넓이 $=\\frac12\\ln\\frac{u_{\\mathrm Q}}{u_{\\mathrm P}}$ (비만의 함수).",
  "접선 교점의 기울기 $=\\frac{\\alpha\\beta-1}{\\alpha\\beta+1}$ (곱만의 함수) → $\\beta=4\\alpha$, $\\alpha\\beta=2$."],
 {'C1':("곡선",r"$x^2-y^2=1$ ($x>0$)."),'C3':("(가)",r"$\mathrm{OP}$, $\mathrm{OQ}$, 호로 둘러싸인 넓이 $\ln2$."),'C4':("(나)",r"두 접선의 교점이 $y=\frac13x$ 위."),'C5':("묻는 것",r"$\overline{\mathrm{PQ}}^2=\frac qp$."),'C6':("서로소",r"기약분수.")},
 [("쌍곡선 매개",[r"$(x+y)(x-y)=1$."]),("치환적분",[r"$t=\frac12(v+\frac1v)$."])],
 [("의도",['C1']),("매개",['C1']),("넓이 분해",['C3']),("식",['C3']),("치환",['C3']),("접선",['C4']),("차",['C4']),("곱",['C4']),("위치",['C3','C4']),("거리",['C5']),("답",['C5','C6'])],
 [("$x$축 아래",'C3',[r"$\alpha=\frac1{\sqrt2}<1$ — $\mathrm P$는 아래쪽."]),("교점의 방향",'C4',[r"교점과 원점을 잇는 직선의 기울기 = 현의 기울기."])],
 [("변형 · 넓이 $\\ln3$",[r"(같은 곡선 $C$에서) (가) 두 선분 $\mathrm{OP}$, $\mathrm{OQ}$와 곡선 $C$의 두 점 사이 부분으로 둘러싸인 넓이는 $\ln3$이다. (나) $\mathrm P$, $\mathrm Q$에서의 두 접선의 교점은 직선 $y=\frac13x$ 위에 있다. $\overline{\mathrm{PQ}}^2=\frac qp$일 때, $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수)"],89,r"$\beta=9\alpha$, $\alpha\beta=2$; $\frac{128}9\cdot\frac12\cdot\frac54=\frac{80}9$.")],
 "쌍곡선 $u=x+y$ 매개 → 넓이는 비, 접선은 곱.")

I(P(82),"예상 오답 — $x^2$의 평균 $\\frac13$과 $d$의 평균 $\\frac14$를 곱해 $b_k=\\frac1{12}$로 두어 보정항을 놓친 경우",
 ["$[0,1]$을 $2^k$ 조각으로, $x=\\frac{j+u}{m}$ 치환 → 조각 번호 $j$의 이차식 합.",
  "$b_k=\\frac1{12}-\\frac1{96\\cdot4^k}$ → 두 등비급수."],
 {'C1':("$d(x)$",r"가장 가까운 정수까지의 거리."),'C4':("$f_n$",r"$\sum_{k=0}^n\frac{d(2^kx)}{2^k}$ (다카기 함수)."),'C5':("$a_n$",r"$\int_0^1x^2f_n$."),'C6':("묻는 것",r"$\lim a_n=\frac qp$; $p+q$."),'C7':("서로소",r"기약분수.")},
 [("주기 조각 치환",[r"$\int_{j/m}^{(j+1)/m}$."]),("등비급수",[r"공비 $\frac12$, $\frac18$."])],
 [("의도",['C5']),("$d$ 성질",['C1']),("조각 치환",['C4']),("식",['C5']),("거듭제곱 합",['C5']),("$b_k$",['C5']),("보정항",['C5']),("급수",['C6']),("극한",['C6']),("답",['C6','C7'])],
 [("보정항",'C5',[r"가중치가 상수가 아니라 조각마다 평균이 다름."]),("$k=0$",'C5',[r"$b_0=\frac7{96}$도 같은 식."])],
 [("변형 · 가중치 $x$",[r"(같은 $d(x)$와 $f_n(x)$에 대하여) $a_n=\int_0^1x\,f_n(x)dx$라 할 때, $\lim_{n\to\infty}a_n=\frac qp$이다. $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)"],5,r"$b_k=\frac18$ (보정항 없음) → $\frac14$.")],
 "자기유사 함수의 가중 적분 → 조각 치환 + 보정항.")

I(P(83),"예상 오답 — 순환 블록의 두 방향을 하나로 세거나 블록 분해 없이 직접 세다 경우를 빠뜨린 경우",
 ["왼쪽 열부터: (ㄱ) 한 열 맞바꿈, (ㄴ) 두 열 가로 맞바꿈, (ㄷ) $2\\times k$ 둘레 순환(두 방향).",
  "맞바꾼 쌍 수: (ㄱ) $1$, (ㄴ) $2$, (ㄷ) $0$ → 블록 나열로 셈."],
 {'C1':("좌석",r"2행 6열, $12$명."),'C2':("이웃",r"옆 또는 같은 열."),'C3':("옮겨 앉기",r"모두 이웃 좌석으로, 각 방법 동등."),'C4':("사건",r"맞바꾼 쌍이 $2$개일 확률 $\frac qp$."),'C5':("묻는 것",r"$p+q$."),'C6':("서로소",r"기약분수.")},
 [("블록 분해",[r"첫 열의 선택이 블록을 닫음."]),("점화식",[r"$N_n=N_{n-1}+N_{n-2}+2\sum_{j\le n-2}N_j$."])],
 [("의도",['C3']),("좌석 이름",['C1']),("블록",['C2','C3']),("독립",['C3']),("$N_n$",['C3']),("쌍의 수",['C4']),("세기",['C4']),("답",['C5','C6'])],
 [("두 방향",'C3',[r"순환은 시계·반시계 두 가지."]),("(ㄴ)",'C4',[r"두 열 가로 맞바꿈 하나로 $2$쌍."])],
 [("변형 · 2행 5열",[r"2행 5열로 배열된 $10$개의 좌석에 $10$명이 앉아 있고, (같은 규칙으로) 모두 이웃한 좌석으로 옮겨 앉는 방법 중 하나를 임의로 택한다. 서로 상대의 원래 좌석으로 옮겨 앉은 두 사람의 쌍의 개수가 $2$일 확률이 $\frac qp$일 때, $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수)"],37,r"$N_5=64$ 중 $10$가지 → $\frac5{32}$.")],
 "격자 위 이웃 이동 = 왼쪽부터 블록 분해.")

