 {'C1':("타원 $E$",r"초점 $\mathrm F(-4,0)$, $\mathrm O$, 장축 $12$."),'C2':("쌍곡선 $H$",r"초점 $\mathrm O$, $\mathrm K(k,0)$, 주축 $3$, $k>3$."),'C4':("(가)",r"$x$축 위에서 만남."),'C5':("(나)",r"$x$축 밖에서도 만남."),'C6':("묻는 것",r"$|\vec{\mathrm{PF}}+\vec{\mathrm{PK}}|^2$.")},
 [("거리의 제곱 차",[r"$\overline{\mathrm{XF}}^2-\overline{\mathrm{XO}}^2=8x+16$."]),("중선 정리",[r"$|\vec a+\vec b|^2=2|\vec a|^2+2|\vec b|^2-|\vec a-\vec b|^2$."])],
 [("두 후보",['C4']),("제곱 차",['C1','C2']),("$k=11$",['C5']),("$k=5$",['C5']),("$\\mathrm P$",['C6']),("답",['C6'])],
 [("$k=11$",'C5',[r"$y^2=0$ 또는 음수 — 다시 $x$축."]),("$\\overline{\\mathrm{XK}}=r\\pm3$",'C2',[r"가지에 따라 두 경우."])],
 [("변형 · $\\vec{\\mathrm{PO}}+\\vec{\\mathrm{PK}}$",[r"(같은 두 곡선 $E$, $H$와 점 $\mathrm P$에 대하여) $|\vec{\mathrm{PO}}+\vec{\mathrm{PK}}|^2$의 값을 구하시오."],209,r"$\mathrm P(-2,4\sqrt2)$, $(9,-8\sqrt2)$.")],
